-- Ex Machinis game data: resources, protocols, their effects, queries and
-- where minerals can be mined. GENERATED by game-data/build_game_data.py from
-- game-data/resources.xlsx, game-data/queries.xlsx and documents/economy.xlsx.
-- Do not edit by hand: change a spreadsheet and run the script again.
--
-- Loading it replaces these tables. Run it on a new database after
-- create_db.sql and db-backup/exmachinis_tables.sql.

SET FOREIGN_KEY_CHECKS = 0;
-- An effect's quantity can name a stack parameter (-1, -2...): older
-- databases have the column unsigned
ALTER TABLE `resource_effects` MODIFY `quantity` INT NULL;
-- Query 803's SQL is longer than the old 512-character column
ALTER TABLE `queries` MODIFY `script` VARCHAR(2000) NOT NULL;
-- What each drone holds: the sum over each state (installed, locked) of
-- its latest inventory event (same as create_db.sql, for older databases)
CREATE OR REPLACE VIEW `sqInventory` AS
SELECT e.`drone` AS `drone`, e.`resource` AS `resource`, CAST(SUM(e.`new_quantity`) AS SIGNED) AS `units`
FROM `events` e
JOIN (
  SELECT MAX(`id`) AS `id`
  FROM `events`
  WHERE `outcome` = 1 AND `event_type` IN (1, 2)
  GROUP BY `drone`, `resource`, `installed`, `locked`
) latest ON latest.`id` = e.`id`
GROUP BY e.`drone`, e.`resource`;
START TRANSACTION;

DELETE FROM `resources`;

DELETE FROM `protocols`;

-- Event types the engines handle (8: launch a drone, #238)

-- Hulls of drones launched from ship kits (same ID as the kit)
ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), cargo_capacity = VALUES(cargo_capacity), a_slots = VALUES(a_slots), b_slots = VALUES(b_slots), c_slots = VALUES(c_slots), d_slots = VALUES(d_slots), e_slots = VALUES(e_slots);

DELETE FROM `resource_effects`;

DELETE FROM `location_effects`;

DELETE FROM `market_effects`;

-- Asteroids, comets and rings (game-data/bodies.csv)
DELETE FROM `objects` WHERE object_id IN (191, 192, 193, 194, 195, 196, 197, 198, 199, 200, 201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215);

-- Planets: argument of periapsis and mean anomaly at J2000, precise semi-major axes
UPDATE `objects` SET semimajor_axis = 57909227, periapsis_argument = 29.12703, mean_anomaly = 174.792527, mean_angular_motion = 4.092329039 WHERE object_id = 1; -- Mercury
UPDATE `objects` SET semimajor_axis = 108209475, periapsis_argument = 54.922625, mean_anomaly = 50.376632, mean_angular_motion = 1.602117115 WHERE object_id = 2; -- Venus
UPDATE `objects` SET semimajor_axis = 149598261, periapsis_argument = 102.937682, mean_anomaly = 357.52689, mean_angular_motion = 0.98560381 WHERE object_id = 3; -- Earth
UPDATE `objects` SET semimajor_axis = 227943822, periapsis_argument = 286.496831, mean_anomaly = 19.390198, mean_angular_motion = 0.524023124 WHERE object_id = 4; -- Mars
UPDATE `objects` SET semimajor_axis = 778340817, periapsis_argument = 274.254571, mean_anomaly = 19.667961, mean_angular_motion = 0.083049588 WHERE object_id = 5; -- Jupiter
UPDATE `objects` SET semimajor_axis = 1426666414, periapsis_argument = 338.936454, mean_anomaly = 317.355366, mean_angular_motion = 0.033466364 WHERE object_id = 6; -- Saturn
UPDATE `objects` SET semimajor_axis = 2870658171, periapsis_argument = 96.937351, mean_anomaly = 142.283828, mean_angular_motion = 0.011725192 WHERE object_id = 7; -- Uranus
UPDATE `objects` SET semimajor_axis = 4498396417, periapsis_argument = 273.180537, mean_anomaly = 259.915208, mean_angular_motion = 0.005977308 WHERE object_id = 8; -- Neptune
UPDATE `objects` SET semimajor_axis = 5906440597, periapsis_argument = 113.76498, mean_anomaly = 14.860122, mean_angular_motion = 0.003972862 WHERE object_id = 9; -- Pluto

DELETE FROM `abundancies`;

DELETE FROM `queries`;

COMMIT;
SET FOREIGN_KEY_CHECKS = 1;
